contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint d, uint a) public payable {
        require(address(this).balance >= d);
        c.SetMinSum(0);
        c.Deposit{value: d}();
        uint beforeBal = c.balances(address(this));
        uint beforeCtr = address(this).balance;
        require(beforeBal >= d);
        require(a <= beforeBal);
        c.Collect(a);
        uint afterBal = c.balances(address(this));
        assert(afterBal == beforeBal - a && address(this).balance == beforeCtr + a);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint minSum, uint amt) public {
        require(minSum > 0);
        c.SetMinSum(minSum);
        c.Deposit{value: amt}();
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;
        bool reverted;
        try c.Collect(amt) { reverted = false; } catch { reverted = true; }
        assert(!reverted
            && c.balances(address(this)) == balBefore
            && address(c).balance == contractBalBefore
            && address(this).balance == myBalBefore);
    }
}

