    bool rejectPayout;

    constructor(C _c) { c = _c; }

    function run(uint d, uint a) public payable {
        require(address(this).balance >= d);
        require(a <= d);
        c.SetMinSum(0);
        c.Deposit{value: d}();
        uint b0 = c.balances(address(this));
        uint cb0 = address(c).balance;
        rejectPayout = true;
        bool reverted;
        try c.Collect(a) {
