contract InvMutTest {
    C c;
    bool inCallback;
    uint duringBal;
    bool sawCallback;

    constructor(C _c) { c = _c; }

    function run(uint d, uint a) public payable {
        require(address(this).balance >= d);
        require(a <= d);
        c.SetMinSum(0);
        c.Deposit{value: d}();
        uint b0 = c.balances(address(this));
        uint cb0 = address(c).balance;
        require(cb0 >= d);
        inCallback = true;
        sawCallback = false;
        bool reverted;
        try c.Collect(a) {
            reverted = false;
        } catch {
            reverted = true;
        }
        inCallback = false;
        assert(
            !reverted && sawCallback &&
            duringBal == b0 - a &&
            c.balances(address(this)) == b0 - a &&
            address(c).balance == cb0 - d
        );
    }

    receive() external payable {
        if (inCallback) {
            duringBal = c.balances(address(this));
            sawCallback = true;
        }
    }
}

